// FNV-1a, used to fingerprint simulation state.
//
// This is the mechanism behind the golden-replay tests: run a known seed and a known
// input sequence, hash the world at checkpoints, and compare against a recorded
// value. A refactor that accidentally changes gameplay shows up as a hash mismatch
// rather than as a bug report six months later. The same fingerprint is what a
// multiplayer desync check compares between host and client.
//
// FNV-1a is chosen for being trivially implementable identically everywhere, not for
// cryptographic strength — this guards against accidents, not adversaries.

const FNV_OFFSET = 2166136261;
const FNV_PRIME = 16777619;

export class Hasher {
  private h = FNV_OFFSET >>> 0;
  private readonly scratch = new DataView(new ArrayBuffer(8));

  /** Hashes the raw bytes of any typed array or buffer view. */
  bytes(view: ArrayBufferView): this {
    const u8 = new Uint8Array(view.buffer, view.byteOffset, view.byteLength);
    let h = this.h;
    for (let i = 0; i < u8.length; i++) {
      h ^= u8[i]!;
      h = Math.imul(h, FNV_PRIME) >>> 0;
    }
    this.h = h;
    return this;
  }

  /**
   * Hashes only the first `elements` entries of a typed array.
   *
   * Component columns are allocated with spare capacity, so hashing the whole array
   * would fold in uninitialised tail slots and make the fingerprint depend on
   * allocation history rather than on game state.
   */
  slice(array: ArrayBufferView & { BYTES_PER_ELEMENT: number }, elements: number): this {
    const bytes = Math.min(array.byteLength, elements * array.BYTES_PER_ELEMENT);
    return this.bytes(new Uint8Array(array.buffer, array.byteOffset, bytes));
  }

  u32(n: number): this {
    this.scratch.setUint32(0, n >>> 0, true);
    return this.bytes(new Uint8Array(this.scratch.buffer, 0, 4));
  }

  i32(n: number): this {
    this.scratch.setInt32(0, n | 0, true);
    return this.bytes(new Uint8Array(this.scratch.buffer, 0, 4));
  }

  /**
   * Hashes a float by its f64 bit pattern, normalising -0 to +0 and every NaN to a
   * single canonical NaN — otherwise two runs that are numerically identical could
   * still disagree on the sign of a zero.
   */
  f64(n: number): this {
    const v = n === 0 ? 0 : Number.isNaN(n) ? Number.NaN : n;
    this.scratch.setFloat64(0, v, true);
    return this.bytes(new Uint8Array(this.scratch.buffer, 0, 8));
  }

  string(s: string): this {
    let h = this.h;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i) & 0xff;
      h = Math.imul(h, FNV_PRIME) >>> 0;
      h ^= (s.charCodeAt(i) >>> 8) & 0xff;
      h = Math.imul(h, FNV_PRIME) >>> 0;
    }
    this.h = h;
    return this;
  }

  get value(): number {
    return this.h >>> 0;
  }

  /** Zero-padded 8-character hex — the form to paste into a golden test. */
  hex(): string {
    return this.value.toString(16).padStart(8, "0");
  }
}

export const hashString = (s: string): number => new Hasher().string(s).value;
