// Manifest-driven asset loading.
//
// The orchestration only: what to load, in what order, how far along, and what to do
// when one fails. The code that actually turns a URL into a `Texture` is injected —
// `assetLoaders.ts` supplies the real one, and a spec supplies a fake. That is what
// makes any of this testable without a browser, and the fetching itself is the part
// with no logic in it.
//
// ── A failed asset must not take the run down ────────────────────────────────────
//
// The tempting shape is `Promise.all`, which rejects on the first failure and leaves
// the player looking at a loading screen forever because one decorative texture 404ed.
// A missing asset is recorded and the game starts without it. The renderer already
// falls back to a flat colour for a texture it does not have, so the failure mode is
// "the background is plain" rather than "the game does not boot" — and `missing` is
// there so the smoke and the console can say which one it was.

import type { Texture } from "three";
import type { AssetManifest, AssetSpec } from "@content/schemas/assets.js";

export interface AssetProgress {
  /** Assets settled so far, loaded or failed. */
  readonly settled: number;
  readonly total: number;
  /** `settled / total`, and 1 for an empty manifest rather than NaN. */
  readonly fraction: number;
  /** The asset that just settled, for a loading screen that names what it is doing. */
  readonly id: string;
}

export interface AssetBundle {
  /** The loaded value, or undefined if it is unknown or failed. */
  get(id: string): unknown;
  /** The loaded value as a texture, or undefined. */
  texture(id: string): Texture | undefined;
  /** Ids that failed to load, in manifest order. Empty on a clean load. */
  readonly missing: readonly string[];
}

/** Turns one spec into its loaded value. Injected so the orchestration is testable. */
export type AssetFetcher = (spec: AssetSpec) => Promise<unknown>;

/**
 * Loads every asset in the manifest, reporting progress as each settles.
 *
 * Concurrent rather than sequential: these are independent files and a serial waterfall
 * would make the loading screen the slowest part of booting. Progress therefore arrives
 * in completion order, not manifest order — which is why `AssetProgress` carries the id
 * rather than an index.
 */
export async function loadAssets(
  manifest: AssetManifest,
  fetcher: AssetFetcher,
  onProgress?: (progress: AssetProgress) => void,
): Promise<AssetBundle> {
  const total = manifest.assets.length;
  const values = new Map<string, unknown>();
  const failures = new Set<string>();
  let settled = 0;

  const report = (id: string): void => {
    settled++;
    onProgress?.({
      settled,
      total,
      // No `total === 0` guard here, deliberately: `report` runs once per asset, so a
      // zero total is unreachable on this path. The audit caught it as dead code — a
      // mutation aimed at it survived, because nothing could reach it. The empty
      // manifest is handled below, where it actually happens.
      fraction: settled / total,
      id,
    });
  };

  await Promise.all(
    manifest.assets.map(async (spec) => {
      try {
        values.set(spec.id, await fetcher(spec));
      } catch {
        // Swallowed on purpose — see the header. The id is recorded so the caller can
        // say what is missing; rethrowing would strand the player on a loading screen.
        failures.add(spec.id);
      }
      report(spec.id);
    }),
  );

  // An empty manifest still gets a final report, and its fraction is 1 rather than the
  // `0/0` a division would give. That NaN renders as a bar of NaN% width — invisible,
  // and never going away — on a loading screen that waits for `fraction === 1`.
  if (total === 0) onProgress?.({ settled: 0, total: 0, fraction: 1, id: "" });

  // Manifest order rather than completion order: a stable list reads the same in every
  // bug report, and completion order is a race.
  const missing = manifest.assets.map((s) => s.id).filter((id) => failures.has(id));

  return {
    get: (id) => values.get(id),
    texture: (id) => values.get(id) as Texture | undefined,
    missing,
  };
}
