// Spawns projectiles from player intent.
//
// The mechanic is now data-driven: everything that used to be a module constant here
// lives in a `WeaponDef` (`@content/weapons`). The structure is unchanged — read input,
// consume a cooldown, draw spread from the seeded RNG, push an event — but the numbers
// belong to content, which is what lets M3's upgrades work without this file knowing
// upgrades exist. The sim only ever sees a resolved `WeaponDef`.
//
// The weapon is read from the firing ship's RESOLVED STATS, so a run carries a loadout
// and two players in one party can fly differently-tuned versions of the same authored
// gun. Nothing here knows what an upgrade is — it reads a `WeaponDef` whose numbers
// were folded once at run start (see `sim/stats.ts`).

import { Vec3, tv3 } from "@core/math/index.js";
import { idleInputFrame, isButtonDown } from "@core/input.js";
import { Button } from "../buttons.js";
import type { SimWorld } from "../world.js";
import type { TickInputs } from "../step.js";

const position = new Vec3();
const velocity = new Vec3();

export function firingSystem(world: SimWorld, inputs: TickInputs): void {
  const { ship, transform, aim: aimStore } = world.components;

  // Cooldowns tick for EVERY ship, whether or not it is firing — otherwise a player
  // who holds the trigger would be timed differently from one who taps it.
  for (let row = 0; row < ship.count; row++) {
    const remaining = ship.columns.fireCooldown[row]!;
    if (remaining > 0) ship.columns.fireCooldown[row] = remaining - 1;
  }

  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const s = ship.row(entity);
    if (s < 0 || ship.columns.fireCooldown[s]! > 0) continue;

    // A destroyed hull does not shoot. `isAlive` above is about the ENTITY HANDLE — the
    // wreck keeps its handle until the run ends, so it is not the check that matters
    // here. Without this a downed player holding the trigger kept firing, and the
    // wreck's kills kept crediting its slot: destroy-N stops, wave clears, drop rolls.
    if (ship.columns.health[s]! <= 0) continue;

    const frame = inputs[slot] ?? idleInputFrame(world.tick);
    if (!isButtonDown(frame, Button.Fire)) continue;

    // Per slot, not per world: in co-op each player brings their own loadout.
    const weapon = world.statsFor(slot).weapon;

    const t = transform.row(entity);
    const a = aimStore.row(entity);
    if (t < 0 || a < 0) continue;

    // Shots follow the RETICLE, not the nose. FLIGHT_AND_AIM.md: "Lasers fire toward
    // the reticle, so shots track where you're aiming even while the ship is still
    // turning to follow." Firing along the ship's orientation instead would defeat
    // the entire point of the reticle-leads/heading-lags model — the lag would cost
    // you accuracy rather than just looking like a ship banking into a turn.
    const forward = tv3().readFrom(aimStore.columns.aimDir, a * 3);

    // Spread comes from the world RNG, so two runs of the same replay produce
    // identical shots — and so a client predicting its own fire agrees with the
    // host about where the bolt went.
    forward.x += world.rng.range(-weapon.spread, weapon.spread);
    forward.y += world.rng.range(-weapon.spread, weapon.spread);
    forward.z += world.rng.range(-weapon.spread, weapon.spread);
    forward.normalize();

    position
      .readFrom(transform.columns.pos, t * 3)
      .addScaledVector(forward, weapon.muzzleForward);
    velocity.copy(forward).multiplyScalar(weapon.projectileSpeed);

    world.spawnProjectile(
      entity,
      slot,
      position,
      velocity,
      weapon.projectileLifetimeTicks,
      weapon.damage,
    );
    ship.columns.fireCooldown[s] = weapon.fireIntervalTicks;
  }
}

