// The simulation world — everything the game state consists of, and nothing else.
//
// If it is not reachable from a SimWorld, it is not game state: it cannot be
// snapshotted, cannot be sent to a client, and cannot be replayed. That is the test
// to apply when deciding where a piece of data belongs. Camera view mode is a good
// example of a judgement call that goes the non-obvious way — it lives in the
// simulation, because aiming is view-relative and a client predicting its own ship
// must agree with the host about which way that ship is facing.

import { EventQueue } from "@core/events.js";
import { Hasher } from "@core/hash.js";
import { Rng } from "@core/rng.js";
import { World, type Entity } from "@core/ecs.js";
import { Quat, Vec3 } from "@core/math/index.js";
import { defineComponents, NO_WAVE, type Components } from "./components.js";
import type { AimMode } from "./flight.js";
import type { RailNetwork } from "./rail.js";
import { createStopState, type StopState } from "./stops.js";
import type { SpawnConfig } from "./spawn.js";
import { computeSplit, splitRngFor } from "./split.js";
import { variantFor } from "./enemy.js";
import { pickupRngFor, rollsDrop } from "./pickups.js";
import type { Wave } from "./waves.js";
import { Faction, type FactionId } from "./faction.js";
import { baseShipStats, type ShipStats } from "./stats.js";
import { HAZARD_ORDER } from "@content/hazards/index.js";
import { ENEMY_ORDER } from "@content/enemies/index.js";
import { PICKUP_ORDER } from "@content/pickups/index.js";
import { WEAPONS } from "@content/weapons/index.js";
import { DEFAULT_SHIP } from "@content/ships/index.js";
import type { HazardDef, HazardSplit } from "@content/schemas/hazard.js";
import type { EnemyDef } from "@content/schemas/enemy.js";
import type { PickupDef } from "@content/schemas/pickup.js";
import type { WeaponCatalog } from "@content/schemas/weapon.js";

/**
 * What a slot flies with nothing equipped.
 *
 * Resolved once at module load rather than per world: it is a pure function of two
 * frozen catalogs, and every `ShipStats` is deeply immutable, so sharing one object
 * across worlds is safe. A test that wants different stats assigns into
 * `statsBySlot` rather than mutating this.
 */
const DEFAULT_SHIP_STATS: ShipStats = baseShipStats(DEFAULT_SHIP, WEAPONS);

/** A run is undecided until it is won or lost; neither is reversible. */
export type RunOutcome = "running" | "won" | "lost";
import type { SimEvent } from "./events.js";

export const MAX_PLAYERS = 6;

export interface SimConfig {
  /** Seeds every random decision in the run. Part of the replay identity. */
  seed: number;
  /** Simulation frequency. Must match the clock driving `stepSim`. */
  hz?: number;
}

export class SimWorld {
  readonly ecs: World;
  readonly rng: Rng;
  readonly events = new EventQueue<SimEvent>();
  readonly components: Components;

  readonly hz: number;
  /** Seconds per tick. Constant — this is a fixed-timestep simulation. */
  readonly dt: number;
  readonly seed: number;

  /** The simulation's only clock. */
  tick = 0;

  /** Ship entity per player slot, or NULL for an empty slot. */
  readonly shipBySlot: (Entity | undefined)[] = new Array(MAX_PLAYERS).fill(undefined);

  // ── The party's rail state ──────────────────────────────────────────────────
  // Deliberately world state rather than per-ship components: in co-op the whole
  // party rides one rail. That is what keeps the network cost at `courseId` plus
  // `railS` — five bytes for six players — instead of a position per ship.

  /** The level's rail. Null before a run starts. Immutable content, never mutated. */
  rail: RailNetwork | null = null;
  /** Which flattened course the party is on. The host decides at a fork. */
  courseId = 0;
  /** Distance travelled along that course, in world units. */
  railS = 0;
  /** Travel speed in world units per second. Run configuration, not mutable state. */
  railSpeed = 30;
  /** True while a waypoint stop parks the rail. Set by the stop system (step 4). */
  railHolding = false;
  /**
   * Aim mode forced by an active stop, overriding each player's own toggle.
   *
   * Derived from the stop state rather than being independent — so it is
   * deliberately NOT hashed; the stop state it comes from is.
   */
  forcedAimMode: AimMode | null = null;

  /** The party's waypoint-stop state. */
  readonly stop: StopState = createStopState();
  /**
   * Waypoint indices whose stop has already been satisfied, sorted.
   *
   * Kept so a cleared stop does not re-park the party on a course that revisits it.
   * Sorted rather than a Set so the fingerprint has a stable iteration order.
   */
  readonly clearedStops: number[] = [];
  /** Hazards destroyed this run. The baseline for a destroy-N stop. */
  hazardsDestroyed = 0;

  /**
   * Triggers fired so far this run, sorted.
   *
   * Game state, so it is hashed — a party that cleared the gate stop is not in the
   * same state as one that skipped it, even if everything else lines up. Sorted array
   * rather than a `Set` for the same reason `clearedStops` is one: the fingerprint
   * needs a stable iteration order, and `Set` iteration follows insertion.
   */
  readonly firedTriggers: string[] = [];

  /**
   * Commit point of the last fork resolved, or -1.
   *
   * How the fork system knows what it has already decided. A single float works
   * because `commitS` ascends along a course and `railS` only ever increases, so
   * "resolved" is exactly "commitS at or behind this mark" — no per-fork bookkeeping,
   * and five bytes of rail state stay five bytes.
   */
  lastForkS = -1;

  /**
   * The hazard archetypes this run may spawn, in `defId` order.
   *
   * Run configuration rather than a global import, so a test can stand up a world with
   * its own catalog — and so the ORDER, which every instance stores as a one-byte
   * index, is an explicit property of the run rather than an accident of module
   * evaluation. Not hashed: it is configuration, fixed for the run, and the `defId`
   * values that reference it are hashed with the component columns.
   */
  hazardCatalog: readonly HazardDef[] = HAZARD_ORDER;

  /**
   * Resolved stats per player slot — hull, rates, and a fully resolved weapon.
   *
   * Folded ONCE at run start by `resolveShipStats` and never touched again, which is
   * what keeps the simulation ignorant of upgrades: it reads numbers, and where they
   * came from is the progression layer's business. Configuration rather than mutable
   * state, so it is not hashed; the mutable half (current `health`) lives on the ship
   * component and is.
   *
   * Per SLOT rather than per entity because a co-op party is six different loadouts,
   * and because a slot outlives the ship in it once respawning exists.
   */
  readonly statsBySlot: ShipStats[] = new Array(MAX_PLAYERS).fill(DEFAULT_SHIP_STATS);

  /**
   * Every weapon this run can resolve by id.
   *
   * Enemies name their gun rather than carrying its numbers, so a def is small and two
   * archetypes can share one weapon. Configuration, not hashed — an enemy instance
   * stores its `defId`, and the def is what names the weapon.
   */
  weaponCatalog: WeaponCatalog = WEAPONS;

  /** The enemy archetypes this run may spawn, in `defId` order. Same rule as hazards. */
  enemyCatalog: readonly EnemyDef[] = ENEMY_ORDER;

  /** The pickup archetypes this run may drop, in `defId` order. Same rule again. */
  pickupCatalog: readonly PickupDef[] = PICKUP_ORDER;

  /**
   * Credits banked this run.
   *
   * Game state, so it is hashed. The simulation only COUNTS them; what they buy is the
   * progression layer's business and lives entirely outside `sim` — this is the hook
   * M3's shop reads at the end of a run.
   */
  credits = 0;

  /**
   * Authored waves, SORTED BY `triggerS`. Run configuration.
   *
   * Sorted because `nextWave` walks them as a cursor: `railS` only ever increases, so
   * a sorted list needs no per-tick scan of the whole level. An unsorted list would
   * silently skip waves, which is why `buildWaves` sorts rather than trusting the
   * author.
   */
  waves: readonly Wave[] = [];
  /**
   * How far through `waves` the run has got. Game state, so it is hashed: two worlds
   * that have released different numbers of waves are not in the same state even if
   * the enemies themselves happen to line up.
   *
   * The cursor advances past a wave belonging to another course WITHOUT spawning it —
   * skipped, not blocked. A wave the party will never see must not hold up the ones
   * behind it.
   */
  nextWave = 0;
  /**
   * Credited kills per wave, parallel to `waves`.
   *
   * Counting kills rather than surviving members is what stops flying past a wave from
   * clearing it: culling removes the enemies but credits nobody, so the count stays
   * short and the trigger never fires.
   */
  readonly waveKills: number[] = [];
  /** Enemies destroyed this run, credited to a player. */
  enemiesDestroyed = 0;

  /** Ambient spawner configuration. Null disables ambient spawning entirely. */
  spawnConfig: SpawnConfig | null = null;
  /**
   * Fractional hazards owed by the ambient rate.
   *
   * Game state, not configuration — it carries between ticks and decides when the
   * next spawn lands, so it belongs in the fingerprint.
   */
  spawnAccrual = 0;

  /** Run outcome. Once decided it never changes, and the rail stops advancing. */
  outcome: RunOutcome = "running";

  constructor({ seed, hz = 60 }: SimConfig) {
    this.seed = seed >>> 0;
    this.hz = hz;
    this.dt = 1 / hz;
    this.rng = new Rng(this.seed);
    this.ecs = new World();
    this.components = defineComponents(this.ecs);
  }

  /**
   * A hash of the complete simulation state.
   *
   * Two uses, both central to the architecture. Golden-replay tests assert this
   * against a recorded value, so an accidental gameplay change surfaces as a diff
   * rather than as a bug report months later. And in multiplayer, host and client
   * compare fingerprints to detect a desync at the tick it happens instead of when
   * it becomes visible.
   *
   * Only live rows are hashed — component columns carry spare capacity, and folding
   * in uninitialised tail slots would make the fingerprint depend on allocation
   * history rather than on game state.
   */
  fingerprint(): string {
    const hasher = new Hasher();
    hasher.u32(this.tick);
    hasher.bytes(this.rng.saveState());
    // The party's rail state is game state, so it belongs in the fingerprint.
    // `railSpeed` does not — it is run configuration, fixed for the run's lifetime.
    hasher.u32(this.courseId).f64(this.railS).u32(this.railHolding ? 1 : 0);
    hasher
      .u32(this.stop.active ? 1 : 0)
      .i32(this.stop.waypoint)
      .u32(this.stop.elapsedTicks)
      .u32(this.stop.killBaseline)
      .u32(this.stop.damaged ? 1 : 0)
      .u32(this.hazardsDestroyed)
      .u32(this.enemiesDestroyed)
      .u32(this.credits)
      .u32(this.nextWave)
      .u32(this.waveKills.length)
      .u32(this.clearedStops.length)
      .f64(this.spawnAccrual)
      .f64(this.lastForkS)
      .u32(this.firedTriggers.length)
      .u32(this.outcome === "running" ? 0 : this.outcome === "won" ? 1 : 2);
    for (const waypoint of this.clearedStops) hasher.u32(waypoint);
    for (const trigger of this.firedTriggers) hasher.string(trigger);
    for (const kills of this.waveKills) hasher.u32(kills);

    for (const store of this.ecs.componentStores) {
      hasher.string(store.name).u32(store.count);
      hasher.slice(store.dense, store.count);
      for (const [, column, arity] of store.columnEntries()) {
        hasher.slice(column, store.count * arity);
      }
    }

    // The entity allocator is state too, even though no component holds it. Two
    // worlds with an identical set of live entities can still disagree about which
    // handle the next spawn gets, because the free list's order depends on the order
    // things were destroyed in. Omitting this made such worlds compare EQUAL and
    // then diverge on the next spawn — silent until long after the cause.
    const allocator = this.ecs.allocatorState();
    hasher.u32(allocator.nextIndex).u32(allocator.freeList.length);
    hasher.bytes(allocator.generations);
    for (const index of allocator.freeList) hasher.u32(index);

    return hasher.hex();
  }

  // ── Entity construction ──────────────────────────────────────────────────────
  // Kept on the world rather than scattered through systems so that the set of
  // component combinations that can exist stays small and legible.

  spawnShip(slot: number, position: Vec3, orientation = new Quat()): Entity {
    const { transform, motion, ship, boxOffset, aim, viewState } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);
    orientation.writeTo(transform.columns.rot, t * 4);

    motion.add(entity);

    const s = ship.add(entity);
    ship.columns.slot[s] = slot;
    // From the resolved stats, not a literal: a hull upgrade has to reach the number
    // the ship actually starts with, and there is exactly one place that happens.
    ship.columns.health[s] = this.statsFor(slot).maxHealth;
    ship.columns.fireCooldown[s] = 0;

    // Flight state. `aimDir`/`headDir` are seeded to the ship's nose (local +X
    // rotated by its orientation) and `shipUp` to its wings, so a ship starts
    // pointing where it was placed rather than snapping on the first tick.
    boxOffset.add(entity);
    const a = aim.add(entity);
    const nose = orientation.rotate(new Vec3(1, 0, 0));
    const wings = orientation.rotate(new Vec3(0, 1, 0));
    nose.writeTo(aim.columns.aimDir, a * 3);
    nose.writeTo(aim.columns.headDir, a * 3);
    wings.writeTo(aim.columns.shipUp, a * 3);
    viewState.add(entity);

    this.shipBySlot[slot] = entity;
    this.events.push({ type: "shipSpawned", entity, slot, tick: this.tick });
    return entity;
  }

  /**
   * Spawns one projectile.
   *
   * `faction` is appended rather than woven in so every existing call site keeps its
   * meaning: a shot with no faction stated is a player's, which is what it was before
   * enemies existed. `ownerSlot` is -1 for an enemy's shot.
   */
  spawnProjectile(
    owner: Entity,
    ownerSlot: number,
    position: Vec3,
    velocity: Vec3,
    lifetimeTicks: number,
    damage: number,
    faction: FactionId = Faction.Player,
  ): Entity {
    const { transform, motion, projectile, lifetime } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);

    const m = motion.add(entity);
    velocity.writeTo(motion.columns.vel, m * 3);

    const p = projectile.add(entity);
    projectile.columns.owner[p] = owner;
    projectile.columns.ownerSlot[p] = ownerSlot;
    projectile.columns.damage[p] = damage;
    projectile.columns.faction[p] = faction;

    lifetime.add(entity);
    lifetime.columns.ticks[lifetime.row(entity)] = lifetimeTicks;

    this.events.push({
      type: "projectileFired",
      entity,
      firedBy: owner,
      slot: ownerSlot,
      faction,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  /**
   * Records that an authored trigger has fired. Returns false if it already had.
   *
   * The seam Addendum 3 promised and never built. Idempotent and order-independent —
   * a trigger is a fact about the run, not an event, so firing it twice must not
   * produce a different world than firing it once.
   */
  fireTrigger(id: string): boolean {
    if (this.firedTriggers.includes(id)) return false;
    this.firedTriggers.push(id);
    this.firedTriggers.sort();
    this.events.push({ type: "triggerFired", triggerId: id, tick: this.tick });
    return true;
  }

  hasTrigger(id: string): boolean {
    return this.firedTriggers.includes(id);
  }

  /**
   * Resolved stats for a player slot.
   *
   * Falls back to the unequipped defaults for an out-of-range slot rather than
   * returning undefined, so every caller can read a number without a guard — the
   * alternative is an optional chain at each of half a dozen hot call sites.
   */
  statsFor(slot: number): ShipStats {
    return this.statsBySlot[slot] ?? DEFAULT_SHIP_STATS;
  }

  /** Resolved stats for a ship entity, by its slot. */
  statsForShip(entity: Entity): ShipStats {
    const s = this.components.ship.row(entity);
    return s < 0 ? DEFAULT_SHIP_STATS : this.statsFor(this.components.ship.columns.slot[s]!);
  }

  /** Index of a def in this world's catalog, or -1. The stored `defId`. */
  hazardDefIndex(id: string): number {
    return this.hazardCatalog.findIndex((def) => def.id === id);
  }

  /**
   * Spawns one hazard from a catalog def.
   *
   * Takes a def rather than loose numbers so that everything about a hazard archetype
   * — radius, health, variant count, what it breaks into — has exactly one source. The
   * previous signature took `(position, radius, health)`, which meant a caller could
   * invent a rock the catalog had never heard of and that therefore could not split.
   */
  spawnHazard(def: HazardDef, position: Vec3, variant = 0, velocity?: Vec3): Entity {
    const { transform, motion, hazard } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);

    const m = motion.add(entity);
    if (velocity) velocity.writeTo(motion.columns.vel, m * 3);

    const h = hazard.add(entity);
    hazard.columns.radius[h] = def.radius;
    hazard.columns.health[h] = def.health;
    // Clamped rather than trusted: a def id absent from the catalog would otherwise
    // write 255 and silently make the hazard unsplittable much later.
    hazard.columns.defId[h] = Math.max(0, this.hazardDefIndex(def.id));
    hazard.columns.variant[h] = def.variants > 0 ? variant % def.variants : 0;

    this.events.push({
      type: "hazardSpawned",
      entity,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  /**
   * Destroys a hazard and credits the kill.
   *
   * The counter is what a destroy-N stop measures against its baseline, so it has to
   * be incremented here rather than by whatever caused the destruction — otherwise a
   * new damage source would silently stop counting toward stops.
   */
  destroyHazard(entity: Entity, bySlot = -1, split = true): boolean {
    const { hazard, motion } = this.components;
    const h = hazard.row(entity);
    if (h < 0) return false;

    const position = new Vec3();
    this.readPosition(entity, position);
    // Only a CREDITED kill counts toward a destroy-N stop. Ramming a rock removes it
    // (bySlot -1) but must not advance an objective that asks you to shoot things.
    if (bySlot >= 0) this.hazardsDestroyed++;
    this.events.push({
      type: "hazardDestroyed",
      entity,
      bySlot,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });

    // Read the def BEFORE queuing destruction — the row is still valid here, and the
    // children have to be created from the parent's state rather than from whatever
    // ends up in its slot after the flush.
    const def = this.hazardCatalog[hazard.columns.defId[h]!];
    const velocity = new Vec3();
    const m = motion.row(entity);
    if (m >= 0) velocity.readFrom(motion.columns.vel, m * 3);

    this.ecs.destroyLater(entity);
    if (split && def?.splitsInto) this.splitHazard(entity, def.splitsInto, position, velocity);
    return true;
  }

  /**
   * Spawns the children of a hazard that has just broken.
   *
   * The randomness comes from `splitRngFor`, which derives a stream from the parent's
   * identity and the tick rather than drawing from `this.rng`. That is deliberate and
   * load-bearing: splits are conditional on where the player shot, so drawing from the
   * shared stream would make the ambient spawner's placements depend on how many rocks
   * happened to break. See `split.ts` for the full argument.
   */
  private splitHazard(parent: Entity, split: HazardSplit, position: Vec3, velocity: Vec3): void {
    const childDef = this.hazardCatalog.find((def) => def.id === split.def);
    if (!childDef) return; // validated content cannot hit this; unvalidated should not crash

    const rng = splitRngFor(parent, this.tick, this.seed);
    for (const child of computeSplit(position, velocity, split, childDef, rng)) {
      // One more draw for the variant, from the SAME split stream, so a piece's shape
      // is as reproducible as its trajectory.
      this.spawnHazard(childDef, child.position, rng.int(0, childDef.variants), child.velocity);
    }
  }

  /** Index of a def in this world's enemy catalog, or -1. The stored `defId`. */
  enemyDefIndex(id: string): number {
    return this.enemyCatalog.findIndex((def) => def.id === id);
  }

  /**
   * Spawns one enemy from a catalog def.
   *
   * `station` is in the units its behaviour implies — see `EnemySchema.station`. The
   * variant is derived from the entity handle rather than drawn from `this.rng`,
   * deliberately: an enemy appears when the party reaches a rail distance, which is a
   * consequence of how the player has been flying, so a draw here would shift every
   * later ambient spawn by an amount that depends on the route taken. The handle is
   * already replicated, so every client derives the same shape for free.
   */
  spawnEnemy(
    def: EnemyDef,
    position: Vec3,
    station: number,
    ox: number,
    oy: number,
    facing: Vec3,
    waveId: number = NO_WAVE,
  ): Entity {
    const { transform, motion, enemy } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);
    motion.add(entity);

    const e = enemy.add(entity);
    // Clamped rather than trusted, as with hazards: a def absent from the catalog
    // would otherwise write 255 and make this enemy read some other archetype's
    // behaviour on its first tick.
    enemy.columns.defId[e] = Math.max(0, this.enemyDefIndex(def.id));
    enemy.columns.variant[e] = variantFor(entity, def.variants);
    enemy.columns.health[e] = def.health;
    enemy.columns.radius[e] = def.radius;
    enemy.columns.fireCooldown[e] = 0;
    enemy.columns.station[e] = station;
    enemy.columns.ox[e] = ox;
    enemy.columns.oy[e] = oy;
    enemy.columns.waveId[e] = waveId;
    facing.writeTo(enemy.columns.facing, e * 3);

    this.events.push({
      type: "enemySpawned",
      entity,
      defId: enemy.columns.defId[e]!,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  /**
   * Destroys an enemy and credits the kill.
   *
   * Deliberately a separate counter from `hazardsDestroyed`, which is what a
   * destroy-N stop measures. Folding enemies into that counter would silently change
   * what every existing authored stop asks for — "destroy two" would start counting
   * drones that happened to be nearby. Making enemy kills able to release a stop is
   * wave content, and it belongs in the stop spec rather than here.
   */
  destroyEnemy(entity: Entity, bySlot = -1): boolean {
    const { enemy } = this.components;
    const e = enemy.row(entity);
    if (e < 0) return false;

    const position = new Vec3();
    this.readPosition(entity, position);
    // Only a CREDITED kill counts — toward the run's tally and toward clearing the
    // wave this enemy belongs to. Culling one the party flew past removes it without
    // crediting anybody, which is what stops "fly away from the wave" from opening a
    // gated route for free.
    const def = this.enemyCatalog[enemy.columns.defId[e]!];
    if (bySlot >= 0) {
      this.enemiesDestroyed++;
      this.creditWaveKill(enemy.columns.waveId[e]!);
      // Only a CREDITED kill pays out. Ramming and culling both destroy an enemy
      // without crediting anybody, and either would otherwise let a player farm drops
      // by flying through a formation or away from it.
      if (def) this.dropFrom(entity, def, position);
    }

    this.events.push({
      type: "enemyDestroyed",
      entity,
      bySlot,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    this.ecs.destroyLater(entity);
    return true;
  }

  /** Index of a def in this world's pickup catalog, or -1. The stored `defId`. */
  pickupDefIndex(id: string): number {
    return this.pickupCatalog.findIndex((def) => def.id === id);
  }

  /**
   * Spawns one pickup, sitting still where it was dropped.
   *
   * No `motion` component, deliberately: a pickup that drifts is one the party cannot
   * catch, because it has left the flight line by the time they reach where it fell.
   */
  spawnPickup(def: PickupDef, position: Vec3): Entity {
    const { transform, pickup, lifetime } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);

    const p = pickup.add(entity);
    pickup.columns.defId[p] = Math.max(0, this.pickupDefIndex(def.id));
    pickup.columns.radius[p] = def.radius;

    // Expiry rides the existing `lifetime` component: a pickup counting down is
    // exactly what a projectile counting down is, and a second countdown would be a
    // second thing to keep in step with the first.
    lifetime.add(entity);
    lifetime.columns.ticks[lifetime.row(entity)] = def.lifetimeTicks;

    this.events.push({
      type: "pickupSpawned",
      entity,
      defId: pickup.columns.defId[p]!,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  /**
   * Rolls an enemy's drop table and spawns whatever it leaves behind.
   *
   * The roll comes from `pickupRngFor` — the dying entity's own identity — and not from
   * `this.rng`. Whether a drop happens is conditional on the player's aim, so a shared
   * draw would make every later ambient hazard placement depend on what they shot at.
   * Fourth subsystem under this rule; see `sim/pickups.ts`.
   */
  private dropFrom(entity: Entity, def: EnemyDef, position: Vec3): void {
    const drop = def.drops;
    if (!drop) return;

    const rng = pickupRngFor(entity, this.tick, this.seed);
    if (!rollsDrop(drop, rng)) return;

    const pickupDef = this.pickupCatalog.find((candidate) => candidate.id === drop.pickup);
    if (!pickupDef) return; // validated content cannot hit this

    // Offset clear of the wreck rather than sitting exactly on it, from the SAME
    // stream, so where a drop lands is as reproducible as whether it happened.
    const direction = new Vec3();
    rng.onUnitSphere(direction);
    this.spawnPickup(pickupDef, position.clone().addScaledVector(direction, pickupDef.scatterRadius));
  }

  /**
   * Applies a pickup to a ship and consumes it.
   *
   * Effects are a switch over a tagged union, so a new kind of pickup is a catalog edit
   * plus at most one case here — never a new system.
   */
  collectPickup(entity: Entity, ship: Entity, slot: number): boolean {
    const { pickup, ship: ships } = this.components;
    const p = pickup.row(entity);
    if (p < 0) return false;

    const defId = pickup.columns.defId[p]!;
    const def = this.pickupCatalog[defId];
    if (!def) return false;

    // Health is re-read HERE rather than trusted from the caller's loop guard. A ship
    // can be destroyed earlier in the same tick — by a bolt in the projectile pass, or
    // by a rock in the contact pass — and a wreck must not collect anything. Revive is
    // explicitly not built (see `systems/objectives.ts`), and a repair that put a ship
    // back above zero would be one by accident.
    const s = ships.row(ship);
    if (s < 0 || ships.columns.health[s]! <= 0) return false;

    switch (def.effect.kind) {
      case "repair": {
        // Not consumed if it would do nothing. Slot order decides who reaches a pickup
        // first, and the first ship in the loop is not usually the one who needs it —
        // a repair spent on a full hull is a repair denied to a teammate.
        if (ships.columns.health[s]! >= this.statsFor(slot).maxHealth) return false;
        this.healShip(ship, slot, def.effect.amount);
        break;
      }
      case "credits":
        this.credits += def.effect.amount;
        break;
    }

    // Removed from the pickup store IMMEDIATELY, not merely queued. Destruction is
    // deferred to the end of the tick, so a pickup that was only `destroyLater`ed is
    // still found by every later slot in the same collision pass — four ships flying
    // through one drop collected it four times.
    pickup.remove(entity);
    this.events.push({ type: "pickupCollected", entity, slot, defId, tick: this.tick });
    this.ecs.destroyLater(entity);
    return true;
  }

  /**
   * Restores hull, capped at the slot's RESOLVED maximum.
   *
   * Not at a literal 100: that cap is where a hull upgrade's value shows up, and
   * clamping to the base would silently make the upgrade worth less than the shop says.
   */
  healShip(entity: Entity, slot: number, amount: number): number {
    const { ship } = this.components;
    const s = ship.row(entity);
    if (s < 0) return 0;
    // A wreck is not repairable. Guarded here as well as at the call site because this
    // is public and M3's progression code will reach for it.
    if (ship.columns.health[s]! <= 0) return ship.columns.health[s]!;

    const max = this.statsFor(slot).maxHealth;
    const healed = Math.min(max, ship.columns.health[s]! + amount);
    ship.columns.health[s] = healed;
    return healed;
  }

  /**
   * Credits a kill toward a wave, firing its trigger if that was the last member.
   *
   * The bridge from combat to the rail: clear the wave, open the route. Fired here
   * rather than in a system because `destroyEnemy` is already the single choke point
   * every kill goes through — the same argument that puts the hazard counter there.
   */
  private creditWaveKill(waveId: number): void {
    if (waveId === NO_WAVE) return;
    const wave = this.waves[waveId];
    if (!wave) return;

    const kills = (this.waveKills[waveId] ?? 0) + 1;
    this.waveKills[waveId] = kills;
    if (kills < wave.count) return;

    this.events.push({ type: "waveCleared", waveId: wave.id, tick: this.tick });
    if (wave.firesTrigger) this.fireTrigger(wave.firesTrigger);
  }

  /** Applies damage to a ship. Returns the health remaining. */
  damageShip(entity: Entity, amount: number): number {
    const { ship } = this.components;
    const s = ship.row(entity);
    if (s < 0) return 0;

    const remaining = ship.columns.health[s]! - amount;
    ship.columns.health[s] = remaining;

    // A "take damage" stop releases on the first hit during the hold. Recorded here
    // rather than inferred from the event queue, which the view drains and the sim
    // must not read back.
    if (this.stop.active) this.stop.damaged = true;

    this.events.push({
      type: "shipDamaged",
      entity,
      slot: ship.columns.slot[s]!,
      amount,
      remaining,
      tick: this.tick,
    });
    return remaining;
  }

  /** Reads an entity's position into `out`. Returns false if it has no transform. */
  readPosition(entity: Entity, out: Vec3): boolean {
    const row = this.components.transform.row(entity);
    if (row < 0) return false;
    out.readFrom(this.components.transform.columns.pos, row * 3);
    return true;
  }
}

export function createSimWorld(config: SimConfig): SimWorld {
  return new SimWorld(config);
}
