// Enemy maths, as pure functions.
//
// The systems that use these live in `systems/enemies.ts` and
// `systems/enemySpawn.ts`. Everything here is pure so that the properties that matter
// — how far a station is from the party, how far a nose can swing in a tick, whether
// two enemies weave together — can be asserted directly instead of inferred from
// where an entity ended up after two hundred ticks.
//
// ── The randomness rule, restated because this is where it is easiest to break ──
//
// Enemy decisions are CONDITIONAL on the player. Whether an enemy fires depends on
// where the player flew, whether it is still alive depends on what they shot, and
// which enemies exist at all depends on how far along the rail they have got. So
// anything random an enemy does must come from a stream derived from stable identity,
// never from `world.rng`.
//
// `rng.fork()` is specifically the wrong tool, and it looks right: forking is exactly
// the "give this subsystem its own stream" idiom. But `fork()` reads the parent's
// current state, which means calling it ADVANCES the parent — so forking per shot
// would make every later ambient hazard placement depend on how many times the
// enemies happened to pull the trigger. `sim/split.ts` has the same argument at
// length; this module follows it.
//
// The weave phase is the case where the temptation is strongest, because it is drawn
// once at spawn and spawning feels unconditional. It is not: an enemy appears when the
// party reaches a rail distance, which is a consequence of how the player has been
// flying. Hence `weavePhaseFor`, derived from the entity handle — which is already
// replicated, so every client computes the same value for free.

import { entityGeneration, entityIndex, type Entity } from "@core/ecs.js";
import { mixSeed, Rng } from "@core/rng.js";
import { clamp, Vec3 } from "@core/math/index.js";
import type { EnemyBehavior, EnemyWeave } from "@content/schemas/enemy.js";

/**
 * Salt distinguishing an enemy's stream from any other stream derived from the same
 * entity on the same tick.
 *
 * Nothing today derives two streams from one entity, but the cost of the constant is
 * nil and the cost of discovering the collision later — an enemy's spread correlated
 * with its own debris — is not.
 */
const ENEMY_STREAM = 0x656e_6d79;
/** A second salt, so the weave phase is not the first draw of the firing stream. */
const WEAVE_STREAM = 0x7761_7665;

/**
 * A random stream belonging to one enemy's decisions on one tick.
 *
 * Generation is mixed in alongside the index because entity indices are recycled:
 * without it, the drone that inherits a dead one's slot would fire identical shots.
 */
export function enemyRngFor(entity: Entity, tick: number, seed: number): Rng {
  return new Rng(
    mixSeed(seed, tick, entityIndex(entity), entityGeneration(entity), ENEMY_STREAM),
  );
}

/** An enemy's weave phase, in [0, 1). Derived from its handle, not drawn. */
export function weavePhaseFor(entity: Entity): number {
  return mixSeed(entityIndex(entity), entityGeneration(entity), WEAVE_STREAM) / 4294967296;
}

/**
 * Lateral displacement from the station at `tick`, or 0 for an enemy with no weave.
 *
 * A pure function of the tick, so it needs no per-enemy state and a client that
 * rewinds reproduces it exactly.
 */
export function weaveOffset(
  weave: EnemyWeave | undefined,
  phase: number,
  tick: number,
): number {
  if (!weave || weave.periodTicks <= 0) return 0;
  return weave.amplitude * Math.sin(2 * Math.PI * (tick / weave.periodTicks + phase));
}

/**
 * The absolute rail distance an enemy is holding station at.
 *
 * `station` means different things per behaviour — an absolute distance for a fixed
 * station, a lead ahead of the party otherwise — and this is the one place that
 * difference is interpreted. See `EnemySchema.station`.
 */
export function stationRailS(
  behavior: EnemyBehavior,
  station: number,
  partyS: number,
): number {
  return behavior.kind === "station" ? station : partyS + station;
}

const turnAxis = new Vec3();
const WORLD_UP = new Vec3(0, 1, 0);

/**
 * Rotates unit `current` toward unit `target` by at most `maxAngle` radians.
 *
 * A step rather than an exponential ease, because "turn rate" is the property being
 * authored and a rate is what the cone tests measure. The antiparallel case is not
 * hypothetical here: an enemy the party has just flown past is looking exactly the
 * wrong way, and a naive cross product would give a zero axis and freeze it there.
 */
export function turnToward(current: Vec3, target: Vec3, maxAngle: number): void {
  const angle = Math.acos(clamp(current.dot(target), -1, 1));
  if (angle <= maxAngle || angle < 1e-6) {
    current.copy(target).normalize();
    return;
  }

  turnAxis.crossVectors(current, target);
  if (turnAxis.lengthSq() < 1e-9) {
    turnAxis.crossVectors(current, WORLD_UP);
    if (turnAxis.lengthSq() < 1e-9) turnAxis.crossVectors(current, new Vec3(1, 0, 0));
    if (turnAxis.lengthSq() < 1e-9) return; // genuinely degenerate; leave it alone
  }
  turnAxis.normalize();
  current.applyAxisAngle(turnAxis, maxAngle).normalize();
}

/**
 * Which of a def's meshes an enemy renders as.
 *
 * From the entity handle rather than the RNG — see the note at the top of this file on
 * why spawning is not the unconditional moment it looks like.
 */
export function variantFor(entity: Entity, variants: number): number {
  if (variants <= 1) return 0;
  return mixSeed(entityIndex(entity), entityGeneration(entity)) % variants;
}
