// A dependency-free mutable unit quaternion.
//
// Ship orientation lives in the simulation as a quaternion rather than as a set of
// basis vectors. The old code kept an explicit `_shipUp` and rebuilt a basis matrix
// each frame, which is where the pole-flip class of bugs came from; quaternions plus
// the rotation-minimizing rail frames make that failure mode structurally impossible
// rather than something to guard against.

import type { Vec3 } from "./vec3.js";
import { tv3 } from "./vec3.js";
import { clamp, EPSILON } from "./scalar.js";

export class Quat {
  constructor(
    public x = 0,
    public y = 0,
    public z = 0,
    public w = 1,
  ) {}

  set(x: number, y: number, z: number, w: number): this {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w;
    return this;
  }

  copy(q: Quat): this {
    return this.set(q.x, q.y, q.z, q.w);
  }

  clone(): Quat {
    return new Quat(this.x, this.y, this.z, this.w);
  }

  identity(): this {
    return this.set(0, 0, 0, 1);
  }

  /** Conjugate. For a unit quaternion this is also the inverse. */
  conjugate(): this {
    return this.set(-this.x, -this.y, -this.z, this.w);
  }

  dot(q: Quat): number {
    return this.x * q.x + this.y * q.y + this.z * q.z + this.w * q.w;
  }

  lengthSq(): number {
    return this.dot(this);
  }

  length(): number {
    return Math.sqrt(this.lengthSq());
  }

  normalize(): this {
    const l = this.length();
    if (l < EPSILON) return this.identity();
    const inv = 1 / l;
    return this.set(this.x * inv, this.y * inv, this.z * inv, this.w * inv);
  }

  setFromAxisAngle(axis: Vec3, angle: number): this {
    const half = angle * 0.5;
    const s = Math.sin(half);
    return this.set(axis.x * s, axis.y * s, axis.z * s, Math.cos(half));
  }

  /**
   * The shortest rotation taking UNIT vector `from` onto UNIT vector `to`.
   * Handles the antiparallel case (where the axis is undefined) by picking any
   * perpendicular axis, which is what keeps a 180-degree turn from producing NaN.
   */
  setFromUnitVectors(from: Vec3, to: Vec3): this {
    const d = from.dot(to);
    if (d > 1 - EPSILON) return this.identity();
    if (d < -1 + EPSILON) {
      // Antiparallel: rotate by PI about any axis perpendicular to `from`.
      const axis = tv3(1, 0, 0).crossVectors(from, tv3(1, 0, 0));
      if (axis.lengthSq() < EPSILON) axis.crossVectors(from, tv3(0, 1, 0));
      axis.normalize();
      return this.set(axis.x, axis.y, axis.z, 0);
    }
    const c = tv3().crossVectors(from, to);
    return this.set(c.x, c.y, c.z, 1 + d).normalize();
  }

  /**
   * Orientation from an ORTHONORMAL, right-handed basis given as its three axes.
   * `xAxis` is the ship's nose, matching the convention the existing model uses
   * (nose = local +X, wings = local +Y).
   */
  setFromBasis(xAxis: Vec3, yAxis: Vec3, zAxis: Vec3): this {
    const m00 = xAxis.x, m01 = yAxis.x, m02 = zAxis.x;
    const m10 = xAxis.y, m11 = yAxis.y, m12 = zAxis.y;
    const m20 = xAxis.z, m21 = yAxis.z, m22 = zAxis.z;
    const trace = m00 + m11 + m22;

    if (trace > 0) {
      const s = 0.5 / Math.sqrt(trace + 1);
      return this.set((m21 - m12) * s, (m02 - m20) * s, (m10 - m01) * s, 0.25 / s);
    }
    if (m00 > m11 && m00 > m22) {
      const s = 2 * Math.sqrt(1 + m00 - m11 - m22);
      return this.set(0.25 * s, (m01 + m10) / s, (m02 + m20) / s, (m21 - m12) / s);
    }
    if (m11 > m22) {
      const s = 2 * Math.sqrt(1 + m11 - m00 - m22);
      return this.set((m01 + m10) / s, 0.25 * s, (m12 + m21) / s, (m02 - m20) / s);
    }
    const s = 2 * Math.sqrt(1 + m22 - m00 - m11);
    return this.set((m02 + m20) / s, (m12 + m21) / s, 0.25 * s, (m10 - m01) / s);
  }

  /** this = this * q (apply `q` first, then `this`). */
  multiply(q: Quat): this {
    return this.multiplyQuaternions(this, q);
  }

  /** this = q * this (apply `this` first, then `q`). */
  premultiply(q: Quat): this {
    return this.multiplyQuaternions(q, this);
  }

  multiplyQuaternions(a: Quat, b: Quat): this {
    const ax = a.x, ay = a.y, az = a.z, aw = a.w;
    const bx = b.x, by = b.y, bz = b.z, bw = b.w;
    return this.set(
      aw * bx + ax * bw + ay * bz - az * by,
      aw * by - ax * bz + ay * bw + az * bx,
      aw * bz + ax * by - ay * bx + az * bw,
      aw * bw - ax * bx - ay * by - az * bz,
    );
  }

  /** Spherical interpolation toward `target`, taking the shortest path. */
  slerp(target: Quat, t: number): this {
    if (t <= 0) return this;
    if (t >= 1) return this.copy(target);

    let cos = this.dot(target);
    // Flip one end so we always travel the short way round.
    let tx = target.x, ty = target.y, tz = target.z, tw = target.w;
    if (cos < 0) {
      cos = -cos;
      tx = -tx;
      ty = -ty;
      tz = -tz;
      tw = -tw;
    }

    // Nearly parallel: slerp degenerates (sin -> 0), so lerp and renormalize.
    if (cos > 1 - 1e-7) {
      return this.set(
        this.x + (tx - this.x) * t,
        this.y + (ty - this.y) * t,
        this.z + (tz - this.z) * t,
        this.w + (tw - this.w) * t,
      ).normalize();
    }

    const theta = Math.acos(clamp(cos, -1, 1));
    const sin = Math.sin(theta);
    const a = Math.sin((1 - t) * theta) / sin;
    const b = Math.sin(t * theta) / sin;
    return this.set(
      this.x * a + tx * b,
      this.y * a + ty * b,
      this.z * a + tz * b,
      this.w * a + tw * b,
    );
  }

  /** Rotates `v` in place by this quaternion. Returns `v`. */
  rotate(v: Vec3): Vec3 {
    // v + 2 * cross(q.xyz, cross(q.xyz, v) + q.w * v)
    const { x, y, z, w } = this;
    const tx = 2 * (y * v.z - z * v.y);
    const ty = 2 * (z * v.x - x * v.z);
    const tz = 2 * (x * v.y - y * v.x);
    return v.set(
      v.x + w * tx + (y * tz - z * ty),
      v.y + w * ty + (z * tx - x * tz),
      v.z + w * tz + (x * ty - y * tx),
    );
  }

  /** Angle in radians between two orientations. */
  angleTo(q: Quat): number {
    return 2 * Math.acos(clamp(Math.abs(this.dot(q)), -1, 1));
  }

  isFinite(): boolean {
    return (
      Number.isFinite(this.x) &&
      Number.isFinite(this.y) &&
      Number.isFinite(this.z) &&
      Number.isFinite(this.w)
    );
  }

  equals(q: Quat, eps = EPSILON): boolean {
    return 1 - Math.abs(this.dot(q)) <= eps;
  }

  readFrom(arr: ArrayLike<number>, base: number): this {
    return this.set(arr[base] ?? 0, arr[base + 1] ?? 0, arr[base + 2] ?? 0, arr[base + 3] ?? 1);
  }

  writeTo(arr: { [i: number]: number }, base: number): this {
    arr[base] = this.x;
    arr[base + 1] = this.y;
    arr[base + 2] = this.z;
    arr[base + 3] = this.w;
    return this;
  }
}

// Scratch ring — same contract as `tv3()`: valid only until RING_SIZE further calls.
const RING_SIZE = 32;
const RING: Quat[] = Array.from({ length: RING_SIZE }, () => new Quat());
let ringIndex = 0;

export function tq(): Quat {
  ringIndex = (ringIndex + 1) % RING_SIZE;
  return RING[ringIndex]!.identity();
}
