// The pickup catalog.
//
// Two, deliberately. `repair` is the one the game needed — before it there was no way
// to recover hull, so a long level was decided by the first mistake — and `credits` is
// the hook M3's shop reads. A catalog of eight variations on "a bit more of something"
// would be content, and content is not what this step is for.

import type { PickupCatalog, PickupDef } from "../schemas/pickup.js";

/**
 * Restores a quarter of a base hull.
 *
 * 25 rather than a fraction: an upgraded ship should not heal proportionally faster,
 * or the hull upgrade would improve repair as well as capacity and be worth twice what
 * the shop says. `repair` caps at the resolved maximum, which is where the upgrade's
 * value shows up.
 */
export const REPAIR: PickupDef = {
  id: "pickup.repair",
  radius: 2.2,
  effect: { kind: "repair", amount: 25 },
  lifetimeTicks: 600, // ten seconds — long enough to turn back for, not forever
  scatterRadius: 1.8,
};

export const CREDITS: PickupDef = {
  id: "pickup.credits",
  radius: 2.2,
  effect: { kind: "credits", amount: 50 },
  lifetimeTicks: 600,
  scatterRadius: 1.8,
};

export const PICKUPS: PickupCatalog = {
  [REPAIR.id]: REPAIR,
  [CREDITS.id]: CREDITS,
};

/**
 * The catalog as an ORDERED list — the `defId` every instance stores, so it is part of
 * the wire format and every replay fingerprint. Appending is safe; reordering is not.
 * Same contract as `HAZARD_ORDER` and `ENEMY_ORDER`.
 */
export const PICKUP_ORDER: readonly PickupDef[] = [REPAIR, CREDITS];
