// The loading screen.
//
// Honest about its own size: with a 60 kB bundle and one baked texture this is on
// screen for a few frames on a fast connection, and the temptation is to skip it. It
// exists anyway for the case it is actually for — a cold load over a slow link, where
// the alternative is a black page that looks broken — and because the alternative to
// building it now is discovering at the art pass that boot order has to be rearranged.
//
// It reports what FAILED as well as what loaded. A missing asset does not stop the run
// (see `view/assets.ts`), which means without this the only symptom would be something
// quietly looking wrong, with no clue as to which file.

const STYLE = `
.sw-loading {
  position: fixed; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 14px;
  background: #05070d; color: #cddcf0; z-index: 10;
  font: 13px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  transition: opacity 260ms ease-out;
}
.sw-loading.done { opacity: 0; pointer-events: none; }
.sw-loading-title { letter-spacing: 0.34em; color: #7e8ea8; font-size: 12px; }
.sw-loading-track { width: 220px; height: 3px; background: #16203a; overflow: hidden; }
.sw-loading-fill { height: 100%; width: 0; background: #49d0a0; transition: width 120ms linear; }
.sw-loading-note { color: #7e8ea8; min-height: 1.5em; }
.sw-loading-note.failed { color: #e0b552; }
`;

export interface LoadingScreen {
  /** 0..1. */
  setProgress(fraction: number): void;
  setNote(text: string, failed?: boolean): void;
  /** Fades out and removes itself. Safe to call twice. */
  dismiss(): void;
}

export function createLoadingScreen(parent: HTMLElement = document.body): LoadingScreen {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-loading";
  root.innerHTML = `
    <div class="sw-loading-title">SUN WEASEL</div>
    <div class="sw-loading-track"><div class="sw-loading-fill" data-fill></div></div>
    <div class="sw-loading-note" data-note></div>
  `;
  parent.appendChild(root);

  const fill = root.querySelector("[data-fill]") as HTMLElement;
  const note = root.querySelector("[data-note]") as HTMLElement;
  let dismissed = false;

  return {
    setProgress(fraction) {
      fill.style.width = `${Math.round(Math.min(1, Math.max(0, fraction)) * 100)}%`;
    },

    setNote(text, failed = false) {
      note.textContent = text;
      note.classList.toggle("failed", failed);
    },

    dismiss() {
      if (dismissed) return;
      dismissed = true;
      root.classList.add("done");
      // Removed after the fade rather than on the next frame, and the style with it —
      // otherwise a reload during the transition stacks a second copy of both.
      setTimeout(() => {
        root.remove();
        style.remove();
      }, 300);
    },
  };
}
