// Releasing authored waves, and culling the enemies the party has left behind.
//
// Replaces `systems/enemySpawn.ts`. That file was careful to call itself "not the wave
// system" — a flat sorted list of individual placements, named as such so nobody would
// later discover a wave system had been written under another name. This is the wave
// system, and it subsumes it: a wave of one is a placement.
//
// Three properties, two carried over and one new:
//
//   1. It draws NOTHING from `world.rng`. A wave is released because the player flew
//      somewhere, so a draw here would make every later ambient rock depend on the
//      route taken. Formation slots are pure geometry, so there is nothing to draw —
//      see the header of `sim/waves.ts`.
//   2. It never lets a member appear out of nothing in front of the party. That is
//      what `lead` is for, and validation requires it to clear `SPAWN_MIN_DIST`.
//   3. NEW: a wave belongs to a course. The cursor SKIPS a wave for a course the
//      party is not on rather than blocking on it — a wave they will never see must
//      not hold up the ones behind it.

import { clamp, Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import { stationRailS } from "../enemy.js";
import { patternSlot } from "../waves.js";
import type { MutableRailFrame, Rail } from "../rail.js";
import type { SimWorld } from "../world.js";

/**
 * How far behind the party an enemy must be before it is culled.
 *
 * Deliberately further back than the hazard cull. A rock behind you is scenery; a
 * charger that has just passed through the formation is still turning around, and
 * removing it at the same distance would make the manoeuvre it exists for invisible.
 */
const CULL_BEHIND = 200;

const frame: MutableRailFrame = {
  position: new Vec3(),
  tangent: new Vec3(),
  normal: new Vec3(),
  binormal: new Vec3(),
};
const spawnAt = new Vec3();
const partyPosition = new Vec3();
const partyForward = new Vec3();
const enemyPosition = new Vec3();
const toEnemy = new Vec3();

export function waveSystem(world: SimWorld): void {
  const rail = world.rail;
  if (!rail) return;
  const course = rail.courses[world.courseId];
  if (!course) return;

  cullPassedEnemies(world, course);

  // Waves are sorted by trigger and `railS` only ever increases, so this is a cursor
  // rather than a scan. No outcome gate is needed and none is written: the run ending
  // stops `flightSystem` advancing `railS`, so the cursor stops with it. A guard here
  // would be untestable, which is a good reason not to add one.
  while (world.nextWave < world.waves.length) {
    const wave = world.waves[world.nextWave]!;
    if (world.railS < wave.triggerS) break;

    const index = world.nextWave;
    world.nextWave++;

    // Skipped, not blocked. A wave belonging to the branch the party did NOT take is
    // stepped over so the ones behind it still release on time.
    if (!wave.courses.includes(world.courseId)) continue;

    world.waveKills[index] = 0;
    for (let member = 0; member < wave.count; member++) {
      const slot = patternSlot(wave.pattern, member, wave.count);
      const ox = wave.ox + slot.ox;
      const oy = wave.oy + slot.oy;

      // Absolute for a fixed station, a lead ahead of the party for the two that
      // follow it — the convention `EnemySchema.station` documents.
      const station =
        wave.def.behavior.kind === "station"
          ? wave.triggerS + wave.lead + slot.along
          : wave.lead + slot.along;

      const stationS = clamp(
        stationRailS(wave.def.behavior, station, world.railS),
        0,
        course.length,
      );
      course.frameAt(stationS, frame);

      // Spawned on its station with the weave at zero: the phase comes from the entity
      // handle, which does not exist until `spawnEnemy` returns. The enemy closes the
      // couple of units on its first ticks.
      spawnAt
        .copy(frame.position)
        .addScaledVector(frame.binormal, ox)
        .addScaledVector(frame.normal, oy);

      world.spawnEnemy(wave.def, spawnAt, station, ox, oy, frame.tangent, index);
    }

    world.events.push({
      type: "waveSpawned",
      waveId: wave.id,
      count: wave.count,
      courseId: world.courseId,
      tick: world.tick,
    });
  }
}

/**
 * Removes enemies the party has travelled well past.
 *
 * Same test as the hazard cull — behind the party along the rail's own forward
 * direction, a pure function of world state — and deliberately not a plain distance
 * test, which on a rail that doubles back would delete enemies the party is about to
 * meet again. No kill credit: this is bookkeeping, not a kill, and crediting it would
 * let a player clear a gated wave by flying away from it.
 */
function cullPassedEnemies(world: SimWorld, course: Rail): void {
  const { enemy } = world.components;
  if (enemy.count === 0) return;

  course.sample(world.railS, partyPosition);
  course.tangentAt(world.railS, partyForward);

  for (let row = enemy.count - 1; row >= 0; row--) {
    const entity = enemy.dense[row]! as Entity;
    if (!world.readPosition(entity, enemyPosition)) continue;

    toEnemy.copy(enemyPosition).sub(partyPosition);
    if (toEnemy.dot(partyForward) >= -CULL_BEHIND) continue;

    world.ecs.destroyLater(entity);
  }
}
