// The browser half of asset loading: URL in, value out.
//
// Deliberately separate from `assets.ts`, which holds all the logic and none of the I/O.
// This file is the reverse — it is the part that needs a browser and cannot be unit
// tested, so it is kept to the smallest thing that could possibly work and covered by
// the view smoke instead.

import { SRGBColorSpace, TextureLoader } from "three";
import type { AssetSpec } from "@content/schemas/assets.js";
import type { AssetFetcher } from "./assets.js";

const textures = new TextureLoader();

export const browserFetcher: AssetFetcher = async (spec: AssetSpec) => {
  if (spec.kind === "texture") {
    const texture = await textures.loadAsync(spec.url);
    // Authored as sRGB like every other image; without this the sky renders washed out
    // under the renderer's linear workflow.
    texture.colorSpace = SRGBColorSpace;
    return texture;
  }

  const response = await fetch(spec.url);
  // `fetch` only rejects on network failure — a 404 resolves with `ok: false`, which
  // would otherwise be parsed as JSON and fail with a confusing syntax error instead of
  // the missing file it actually is.
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}: ${spec.url}`);
  return await response.json();
};
