// Cameras, slaved to the simulation's view basis.
//
// This is the payoff of having moved the view basis into `sim`. The camera does not
// derive an orientation of its own — it reads the ship's `head` and transported
// `shipUp` and places itself against them. In the old engine the arrow pointed the
// other way: aiming read `camera.matrixWorld`, which is why six players could never
// have worked, and why the simulation could not run headless.
//
// `shipUp` is the camera's up as well as the ship's. That is deliberate: it is
// parallel-transported rather than rebuilt from world-up, so pitching through the
// vertical does not roll the view over.

import { PerspectiveCamera } from "three";
import { CHASE_AHEAD, CHASE_BACK, CHASE_HEIGHT } from "@content/tuning/flight.js";
import type { FlightState } from "@sim/flight.js";
import { Vec3 } from "@core/math/index.js";

const eye = new Vec3();
const target = new Vec3();

export function createCamera(aspect = 1): PerspectiveCamera {
  const camera = new PerspectiveCamera(70, aspect, 0.1, 4000);
  camera.up.set(0, 1, 0);
  return camera;
}

/**
 * Places `camera` for a ship at `shipPosition` in the mode its flight state carries.
 *
 * Cockpit rides the ship and looks down the heading. Third-person sits back along the
 * heading and above it, looking past the ship so the reticle stays framed — which is
 * the point of the chase view in a game where you aim ahead of where you are.
 */
export function placeCamera(
  camera: PerspectiveCamera,
  shipPosition: Vec3,
  flight: FlightState,
): void {
  camera.up.set(flight.up.x, flight.up.y, flight.up.z);

  if (flight.viewMode === "third") {
    eye
      .copy(shipPosition)
      .addScaledVector(flight.head, -CHASE_BACK)
      .addScaledVector(flight.up, CHASE_HEIGHT);
    target.copy(shipPosition).addScaledVector(flight.head, CHASE_AHEAD);
  } else {
    eye.copy(shipPosition);
    target.copy(shipPosition).addScaledVector(flight.head, CHASE_AHEAD);
  }

  camera.position.set(eye.x, eye.y, eye.z);
  camera.lookAt(target.x, target.y, target.z);
}
