// The game's digital inputs.
//
// These are gameplay vocabulary, so they live in `sim` — `core/input.ts` owns only
// the frame's shape and its 16-bit width. Add new buttons at the END and never
// reorder: the bitfield is part of the wire format, and a reordered bit would make
// an old client's "fire" read as the new client's "boost".

export const Button = {
  Fire: 1 << 0,
  Boost: 1 << 1,
  Brake: 1 << 2,
  Barrel: 1 << 3,
  Ability1: 1 << 4,
  Ability2: 1 << 5,
  ViewToggle: 1 << 6,
  AimMode: 1 << 7,
} as const;

export type ButtonName = keyof typeof Button;

export const ALL_BUTTONS: readonly ButtonName[] = Object.keys(Button) as ButtonName[];
