// The input frame — one player's intent for one simulation tick.
//
// This is the seam that makes multiplayer additive rather than a second rewrite.
// The simulation NEVER reads a keyboard; it consumes `InputFrame`s. Single-player
// is then just "the network with zero latency and one peer", and the code path a
// remote player's input travels is the same one the local player's input travels.
//
// The critical detail is that frames are QUANTIZED AT CONSTRUCTION, not at send
// time. If the local player's stick were full float64 while a remote player's had
// been rounded to int16 on the wire, single-player and multiplayer would feel
// subtly different, and — worse — a predicting client would disagree with the host
// about its own ship by a hair every single tick. Quantizing up front makes the
// local and wire representations identical by construction.

// This module lives in `core` rather than in `net` for a layering reason worth
// stating: the SIMULATION defines what an input is, and the network merely carries
// it. Putting the type in `net` would force `sim` to import from `net`, inverting
// the dependency. It is not in `sim` either, because the quantization and the byte
// layout are engine mechanics with no gameplay meaning — the game-specific button
// NAMES live in `sim/buttons.ts`, and only the bitfield's width is fixed here.

/**
 * One player's intent for one tick.
 *
 * `steerX`/`steerY` are in [-1, 1] and already snapped to the wire's quantization
 * grid. Build these with `makeInputFrame`, never as an object literal, or the
 * quantization guarantee is lost.
 */
export interface InputFrame {
  readonly tick: number;
  readonly steerX: number;
  readonly steerY: number;
  readonly buttons: number;
}

/** Bytes on the wire: u32 tick, i16 steerX, i16 steerY, u16 buttons. */
export const INPUT_FRAME_BYTES = 10;

const STEER_SCALE = 32767;

const clampUnit = (v: number): number => (v < -1 ? -1 : v > 1 ? 1 : Number.isFinite(v) ? v : 0);

/** Snaps an axis to the same grid the wire uses. */
export const quantizeAxis = (v: number): number => Math.round(clampUnit(v) * STEER_SCALE);
export const dequantizeAxis = (q: number): number => q / STEER_SCALE;

/** The only sanctioned way to build an InputFrame. Quantizes the axes. */
export function makeInputFrame(
  tick: number,
  steerX = 0,
  steerY = 0,
  buttons = 0,
): InputFrame {
  return {
    tick: tick >>> 0,
    steerX: dequantizeAxis(quantizeAxis(steerX)),
    steerY: dequantizeAxis(quantizeAxis(steerY)),
    buttons: buttons & 0xffff,
  };
}

/** A neutral frame — no stick, no buttons. */
export const idleInputFrame = (tick: number): InputFrame => makeInputFrame(tick, 0, 0, 0);

export const isButtonDown = (frame: InputFrame, button: number): boolean =>
  (frame.buttons & button) !== 0;

/** Buttons that went down between `previous` and `current` (rising edge). */
export const pressedThisTick = (previous: InputFrame, current: InputFrame): number =>
  current.buttons & ~previous.buttons;

/** Buttons that went up between `previous` and `current` (falling edge). */
export const releasedThisTick = (previous: InputFrame, current: InputFrame): number =>
  previous.buttons & ~current.buttons;

export const inputFramesEqual = (a: InputFrame, b: InputFrame): boolean =>
  a.steerX === b.steerX && a.steerY === b.steerY && a.buttons === b.buttons;

// ── Codec ─────────────────────────────────────────────────────────────────────
// Little-endian throughout. Every platform this ships to is little-endian, but it
// is specified explicitly so the format never depends on host byte order.

export function writeInputFrame(view: DataView, offset: number, frame: InputFrame): number {
  view.setUint32(offset, frame.tick >>> 0, true);
  view.setInt16(offset + 4, quantizeAxis(frame.steerX), true);
  view.setInt16(offset + 6, quantizeAxis(frame.steerY), true);
  view.setUint16(offset + 8, frame.buttons & 0xffff, true);
  return offset + INPUT_FRAME_BYTES;
}

export function readInputFrame(view: DataView, offset: number): InputFrame {
  return {
    tick: view.getUint32(offset, true),
    steerX: dequantizeAxis(view.getInt16(offset + 4, true)),
    steerY: dequantizeAxis(view.getInt16(offset + 6, true)),
    buttons: view.getUint16(offset + 8, true),
  };
}

export function encodeInputFrames(frames: readonly InputFrame[]): Uint8Array {
  const bytes = new Uint8Array(frames.length * INPUT_FRAME_BYTES);
  const view = new DataView(bytes.buffer);
  let offset = 0;
  for (const frame of frames) offset = writeInputFrame(view, offset, frame);
  return bytes;
}

export function decodeInputFrames(bytes: Uint8Array): InputFrame[] {
  const count = Math.floor(bytes.byteLength / INPUT_FRAME_BYTES);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const frames: InputFrame[] = new Array(count);
  for (let i = 0; i < count; i++) frames[i] = readInputFrame(view, i * INPUT_FRAME_BYTES);
  return frames;
}

/**
 * A fixed sequence of input frames addressed by tick.
 *
 * Used by the golden-replay tests to drive a run from a script, and later by the
 * client's prediction buffer. Ticks past the end repeat the last frame's BUTTONS
 * as released and centre the stick, rather than holding the final input forever —
 * a replay that runs off the end of its script should coast, not fly into a wall
 * with the throttle jammed open.
 */
export class RecordedInput {
  private readonly byTick = new Map<number, InputFrame>();
  readonly lastTick: number;

  constructor(frames: readonly InputFrame[]) {
    let last = -1;
    for (const frame of frames) {
      this.byTick.set(frame.tick, frame);
      if (frame.tick > last) last = frame.tick;
    }
    this.lastTick = last;
  }

  at(tick: number): InputFrame {
    return this.byTick.get(tick) ?? idleInputFrame(tick);
  }

  get length(): number {
    return this.byTick.size;
  }

  /**
   * Builds a script by calling `fn` for each tick in `[0, ticks)`. Handy for
   * expressing a replay as "hold right from tick 30 to 60" without writing out
   * every frame by hand.
   */
  static generate(
    ticks: number,
    fn: (tick: number) => { steerX?: number; steerY?: number; buttons?: number } | undefined,
  ): RecordedInput {
    const frames: InputFrame[] = [];
    for (let tick = 0; tick < ticks; tick++) {
      const spec = fn(tick);
      if (spec) frames.push(makeInputFrame(tick, spec.steerX, spec.steerY, spec.buttons));
    }
    return new RecordedInput(frames);
  }
}
