// `view` — everything Three.js, and nothing that decides gameplay.
//
// Reads simulation state and draws it. It never writes to the world: the simulation
// is the authority, and a renderer that could nudge state would take the whole
// architecture's central rule with it. Enforced by the layering rules in
// eslint.config.js — `view` may import `sim`, never the reverse.

import {
  AmbientLight,
  BufferGeometry,
  Color,
  ConeGeometry,
  DirectionalLight,
  Fog,
  Line,
  LineBasicMaterial,
  Mesh,
  MeshStandardMaterial,
  EquirectangularReflectionMapping,
  Scene,
  Vector3,
  WebGLRenderer,
  type PerspectiveCamera,
} from "three";
import type { Entity } from "@core/ecs.js";
import { Quat, Vec3 } from "@core/math/index.js";
import { createFlightState, readFlight, type FlightState } from "@sim/flight.js";
import { MAX_PLAYERS, type SimWorld } from "@sim/world.js";
import { createCamera, placeCamera } from "./cameras.js";
import { createField, type Field } from "./field.js";
import { createReticle, type Reticle } from "./reticle.js";
import { TransformInterpolator } from "./interpolation.js";
import type { AssetBundle } from "./assets.js";
import { STARS } from "@content/assets/index.js";

export { TransformInterpolator } from "./interpolation.js";

/** How finely the rail guide is sampled. Build-time cost only. */
const RAIL_SAMPLES = 400;

/**
 * The device pixel ratio to render at.
 *
 * Capped at 2 on a desktop, as before. Phones are capped harder, at 1.5, because the
 * cost is quadratic and modern handsets report 3: rendering a 3× buffer means nine
 * times the fragments of a 1× one, and on a mid-range phone that is the difference
 * between 60fps and a slideshow. 1.5 is deliberately not 1 — the reticle and the rail
 * guide are thin lines, and they alias badly at 1× on a small screen, which is the one
 * place the extra samples are actually worth their cost.
 *
 * Sniffed on the pointer rather than on a user-agent string: what matters is that this
 * is a small high-density screen, and every UA-based answer to that question has gone
 * stale within a couple of years.
 */
function maxPixelRatio(): number {
  const coarse =
    typeof window.matchMedia === "function" && window.matchMedia("(pointer: coarse)").matches;
  return Math.min(window.devicePixelRatio, coarse ? 1.5 : 2);
}

export interface View {
  readonly renderer: WebGLRenderer;
  readonly camera: PerspectiveCamera;
  readonly scene: Scene;
  readonly interpolator: TransformInterpolator;
  readonly reticle: Reticle;
  /** The instanced hazard/projectile field. Exposed for the smoke's variety check. */
  readonly field: Field;

  /** Builds the rail guide once the world has a rail. Safe to call repeatedly. */
  syncRail(world: SimWorld): void;
  render(world: SimWorld, alpha: number): void;
  /** Projects a world point to viewport pixels. Used by the smoke tests. */
  project(point: Vec3): [number, number, number];
  resize(width: number, height: number): void;
  dispose(): void;
}

const shipPosition = new Vec3();
const shipRotation = new Quat();
const flight: FlightState = createFlightState();
const projected = new Vector3();

export function createView(canvas: HTMLCanvasElement, assets?: AssetBundle): View {
  const renderer = new WebGLRenderer({ canvas, antialias: true });
  renderer.setPixelRatio(maxPixelRatio());

  const scene = new Scene();
  // The flat colour is the FALLBACK, set first and only replaced if the sky actually
  // loaded. A missing asset must leave the game looking plain rather than looking
  // broken — see the header of `view/assets.ts`.
  scene.background = new Color(0x05070d);
  const sky = assets?.texture(STARS);
  if (sky) {
    // Equirectangular, so the 2:1 baked image wraps onto the sky sphere. Without this
    // mapping Three.js treats it as a flat backdrop and it reads as wallpaper.
    sky.mapping = EquirectangularReflectionMapping;
    scene.background = sky;
  }
  // Fog does double duty: atmosphere, and it is what makes a hazard seeded far down
  // the rail FADE in rather than appear. The spawner's minimum distance is chosen to
  // land outside this, so the two have to stay in step.
  scene.fog = new Fog(0x05070d, 60, 400);

  scene.add(new AmbientLight(0x6070a0, 1.2));
  const key = new DirectionalLight(0xfff2e0, 2);
  key.position.set(1, 2, 1);
  scene.add(key);

  const camera = createCamera(canvas.clientWidth / Math.max(1, canvas.clientHeight));
  const field: Field = createField(scene);
  const reticle = createReticle(scene);
  const interpolator = new TransformInterpolator();

  // Ship hulls: a cone nosed along local +X, matching the simulation's convention
  // (nose = +X, wings = +Y) so the orientation quaternion applies unmodified.
  const hullGeometry = new ConeGeometry(0.5, 2, 8);
  hullGeometry.rotateZ(-Math.PI / 2);
  const ships: Mesh[] = [];
  for (let slot = 0; slot < MAX_PLAYERS; slot++) {
    const hull = new Mesh(
      hullGeometry,
      new MeshStandardMaterial({
        color: new Color().setHSL(slot / MAX_PLAYERS, 0.6, 0.55),
        roughness: 0.4,
        metalness: 0.3,
      }),
    );
    hull.visible = false;
    scene.add(hull);
    ships.push(hull);
  }

  let railGuide: Line | null = null;
  let railBuiltFor: unknown = null;

  return {
    renderer,
    camera,
    scene,
    interpolator,
    reticle,

    syncRail(world) {
      const course = world.rail?.courses[world.courseId];
      if (!course || railBuiltFor === course) return;

      if (railGuide) {
        scene.remove(railGuide);
        railGuide.geometry.dispose();
      }
      const points: Vector3[] = [];
      const sample = new Vec3();
      for (let i = 0; i <= RAIL_SAMPLES; i++) {
        course.sample((i / RAIL_SAMPLES) * course.length, sample);
        points.push(new Vector3(sample.x, sample.y, sample.z));
      }
      railGuide = new Line(
        new BufferGeometry().setFromPoints(points),
        new LineBasicMaterial({ color: 0x1f6f8f }),
      );
      scene.add(railGuide);
      railBuiltFor = course;
    },

    render(world, alpha) {
      this.syncRail(world);

      // Ships first: the camera reads slot 0's interpolated transform, so it has to
      // be current before the camera is placed or the view lags the ship by a frame.
      let cameraShip: Entity | undefined;
      for (let slot = 0; slot < MAX_PLAYERS; slot++) {
        const entity = world.shipBySlot[slot];
        const hull = ships[slot]!;
        if (entity === undefined || !world.ecs.isAlive(entity)) {
          hull.visible = false;
          continue;
        }

        interpolator.position(world, entity, alpha, shipPosition);
        interpolator.rotation(world, entity, alpha, shipRotation);
        hull.position.set(shipPosition.x, shipPosition.y, shipPosition.z);
        hull.quaternion.set(shipRotation.x, shipRotation.y, shipRotation.z, shipRotation.w);
        hull.visible = true;
        if (cameraShip === undefined) cameraShip = entity;
      }

      if (cameraShip !== undefined && readFlight(world, cameraShip, flight)) {
        interpolator.position(world, cameraShip, alpha, shipPosition);
        placeCamera(camera, shipPosition, flight);
        // In cockpit the hull would fill the screen from inside; hide it there.
        const hull = ships[world.components.ship.columns.slot[
          world.components.ship.row(cameraShip)
        ]!];
        if (hull) hull.visible = flight.viewMode === "third";

        camera.updateMatrixWorld();
        // After the camera, so the ring billboards to the view it is drawn in.
        reticle.update(shipPosition, flight, camera);
      }

      field.update(world, interpolator, alpha);
      renderer.render(scene, camera);
    },

    field,

    project(point) {
      projected.set(point.x, point.y, point.z).project(camera);
      return [
        (projected.x * 0.5 + 0.5) * renderer.domElement.clientWidth,
        (-projected.y * 0.5 + 0.5) * renderer.domElement.clientHeight,
        projected.z,
      ];
    },

    resize(width, height) {
      renderer.setSize(width, height, false);
      camera.aspect = width / Math.max(1, height);
      camera.updateProjectionMatrix();
    },

    dispose() {
      field.dispose();
      reticle.dispose();
      hullGeometry.dispose();
      for (const hull of ships) (hull.material as MeshStandardMaterial).dispose();
      if (railGuide) railGuide.geometry.dispose();
      renderer.dispose();
    },
  };
}
