// Expires timed entities.
//
// Lifetimes are counted in TICKS, not milliseconds. That is not a stylistic choice:
// a millisecond countdown decremented by a variable frame delta would expire after a
// different number of simulated steps on different machines, and every projectile
// would desync in multiplayer.

import type { Entity } from "@core/ecs.js";
import { Vec3 } from "@core/math/index.js";
import type { SimWorld } from "../world.js";

const scratch = new Vec3();

export function lifetimeSystem(world: SimWorld): void {
  const { lifetime } = world.components;
  const ticks = lifetime.columns.ticks;

  // Iterating backwards is not strictly required — destruction is deferred to the
  // end of the tick — but it keeps this loop correct if that ever changes.
  for (let row = lifetime.count - 1; row >= 0; row--) {
    const remaining = ticks[row]!;
    if (remaining > 1) {
      ticks[row] = remaining - 1;
      continue;
    }

    ticks[row] = 0;
    const entity = lifetime.dense[row]! as Entity;

    // Only a PROJECTILE announces itself as an expiring projectile. This component was
    // written when projectiles were the only timed entity and pushed the event for
    // anything it timed out; pickups now expire the same way, and the first
    // shot-expiry spark would otherwise fire at every uncollected drop. Latent when
    // found — nothing consumes the event yet — which is exactly when it is cheap.
    if (world.components.projectile.row(entity) >= 0) {
      // Read the position BEFORE queuing destruction: the event is a value that the
      // view layer may handle long after the entity is gone.
      scratch.set(0, 0, 0);
      world.readPosition(entity, scratch);
      world.events.push({
        type: "projectileExpired",
        entity,
        x: scratch.x,
        y: scratch.y,
        z: scratch.z,
        tick: world.tick,
      });
    }
    world.ecs.destroyLater(entity);
  }
}
