// The asset manifest.
//
// One place that says what the game needs to load. That is what lets the loading screen
// know how far along it is, lets CI check the files exist, and will let the encrypted
// deploy know what to encrypt — none of which works if an asset can be requested from
// anywhere in the codebase.
//
// Short on purpose. Everything else in the game is procedural geometry, and a manifest
// full of things nobody drew would be scaffolding rather than a pipeline. It grows with
// the art pass.

import type { AssetManifest } from "../schemas/assets.js";

/** Equirectangular star field, baked by `npm run bake`. Used as the sky. */
export const STARS = "sky.stars";

export const ASSETS: AssetManifest = {
  assets: [
    // Relative, with no leading slash: the preview deploys to a SUBDIRECTORY
    // (`games/sun-weasel-next/`), and an absolute path would resolve to the domain
    // root and 404 there while working perfectly in local dev.
    { id: STARS, kind: "texture", url: "assets/stars.png" },
  ],
};
